def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    opp_def = sum(1 for a in opp if a == 'D')
    opp_def_rate = opp_def / n

    # Early safety: if opponent is almost always defecting, defect
    if n >= 10 and opp_def_rate > 0.8:
        return 'D'

    # Learning phase: first 30 rounds
    if n < 30:
        # Scheduled probes to test opponent's response to defection
        if n == 5 or n == 15 or n == 25:
            return 'D'
        # Opening: cooperate to establish trust
        if n < 5:
            return 'C'
        last_my, last_opp = history[-1]
        if last_opp == 'C':
            return 'C'
        else:
            # Opponent defected. Forgive a single defection, punish consecutive defections.
            if n >= 2 and history[-2][1] == 'D':
                return 'D'
            else:
                return 'C'

    # After 30 rounds, decide mode based on opponent's responsiveness.
    if opp_def_rate > 0.5:
        return 'D'

    my = [h[0] for h in history]
    my_c_total = 0
    my_c_opp_def = 0
    my_d_total = 0
    my_d_opp_def = 0
    for i in range(1, n):
        if my[i-1] == 'C':
            my_c_total += 1
            if opp[i] == 'D':
                my_c_opp_def += 1
        else:
            my_d_total += 1
            if opp[i] == 'D':
                my_d_opp_def += 1

    rate_c = my_c_opp_def / my_c_total if my_c_total > 0 else 0.0
    rate_d = my_d_opp_def / my_d_total if my_d_total > 0 else 0.0

    # If opponent retaliates when we defect, they are responsive. Cooperate to keep them cooperating.
    if rate_d > rate_c + 0.25:
        if n == 99:
            return 'D'  # Last round exploitation
        return 'C'
    else:
        # Opponent does not respond to our defections: exploit by always defecting.
        return 'D'
